package lk.repairdesk.api.domain;
import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.Instant;
@Entity @Table(name="repair_requests") @Getter @Setter @NoArgsConstructor
public class RepairRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) private Device device; @ManyToOne(fetch=FetchType.LAZY,optional=false) private User customer; @ManyToOne(fetch=FetchType.LAZY) private User technician; @Column(nullable=false,length=150) private String title; @Column(nullable=false,length=2000) private String description; @Enumerated(EnumType.STRING) @Column(nullable=false) private Priority priority; @Enumerated(EnumType.STRING) @Column(nullable=false) private RepairStatus status=RepairStatus.SUBMITTED; @Column(precision=12,scale=2) private BigDecimal estimatedValue; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now(); @Column(nullable=false) private Instant updatedAt=Instant.now(); @PreUpdate void touch(){updatedAt=Instant.now();} }
